fn zeros_like(a: &Vec<i32>) -> Vec<i32> {
    // Create a new Vec<i32> of the same length as `a`, filled with zeros.
    vec![0; a.len()]
}

#[cfg(test)]
mod tests {
    use super::zeros_like;

    #[test]
    fn test_empty() {
        let a: Vec<i32> = Vec::new();
        let z = zeros_like(&a);
        assert_eq!(z.len(), 0);
        assert!(z.is_empty());
    }

    #[test]
    fn test_non_empty() {
        let a = vec![5, -3, 42, 7];
        let z = zeros_like(&a);
        // Property (1): same length
        assert_eq!(z.len(), a.len());
        // Property (2): all elements zero
        assert!(z.iter().all(|&x| x == 0));
        // Property (3): adding z on either side leaves a unchanged
        let added_left: Vec<i32> = a.iter().zip(&z).map(|(&x, &y)| y + x).collect();
        let added_right: Vec<i32> = a.iter().zip(&z).map(|(&x, &y)| x + y).collect();
        assert_eq!(added_left, a);
        assert_eq!(added_right, a);
    }
}